// Crusaders Mainframe — how a board reaches the club, and what it accepts when
// that changes: the server base URL grammar, the heartbeat's `net` and
// `key_next` objects, and the WiFi link supervisor.
//
// WHY THIS EXISTS
// ---------------
// Device contract v3 (docs/specs/device-api.md §6, §8) made the next USB flash
// the last one, and the founder's rule that follows from it: NOTHING an operator
// does may force a reflash. A new router, a moved server, a rotated device key —
// each used to mean a cable to every board. Now the compiled values in
// `secrets.h` are only the first-boot defaults, and these four rules decide
// what a board will take instead. Both ESP images (the court box's bridge and
// the door gate) compile this one copy, and the server validates what an admin
// saves with the same rules, so a value the console accepts is a value every
// board accepts.
//
// The reference implementation is `src/contracts/device-protocol/provision/
// gen_cases.py`; `shared/test/test_devnet` executes every case it generated.
// Refusal names ARE the corpus `reason` strings (`refusalName`).
//
// No Arduino headers, no heap. C++11-valid. Compiles for AVR, Xtensa, the host.

#ifndef CRUSADERS_DEVNET_NET_H
#define CRUSADERS_DEVNET_NET_H

#include <stddef.h>
#include <stdint.h>

namespace devnet {

/// Longest base URL a board will dial. `provision/` `constants.base_url_max`.
inline constexpr size_t kBaseUrlMax = 96U;
/// WPA2: an SSID is 1–32 bytes, a passphrase 8–63 printable characters (or
/// empty, for an open network).
inline constexpr size_t kSsidMax = 32U;
inline constexpr size_t kPskMax = 63U;
inline constexpr size_t kPskMin = 8U;
/// A device key: 32 bytes as unpadded base64url. Ids are `k1`…`k999999`; `k0`
/// names the compiled key and is never sent.
inline constexpr size_t kKeyLen = 43U;
inline constexpr size_t kKeyIdCap = 8U;
/// Two WiFi profiles per configuration (docs/specs/device-api.md §8).
inline constexpr uint8_t kProfiles = 2U;

/// The link supervisor's constants. Recovery mechanics, not club preferences —
/// a club cannot usefully choose how fast a board retries an access point — so
/// contract constants, pinned by `provision/` `constants`.
inline constexpr uint32_t kSupervisorGraceS = 30U;
inline constexpr uint32_t kSupervisorBackoffS[] = {30U, 60U, 120U, 240U, 300U};
inline constexpr uint8_t kSupervisorBackoffSteps = 5U;
inline constexpr uint32_t kSupervisorRestartS = 900U;

/// Every refusal any rule here can give, named exactly as the corpus names it.
enum class Refusal : uint8_t {
  Ok = 0U,
  // base_urls
  Empty,
  TooLong,
  Https,
  Grammar,
  Host,
  Port,
  // nets
  Ver,
  NotNewer,
  BaseEmpty,
  BaseTooLong,
  BaseHttps,
  BaseGrammar,
  BaseHost,
  BasePort,
  Wifi0Ssid,
  Wifi0Psk,
  Wifi1Ssid,
  Wifi1Psk,
  NetEmpty,
  // keys
  Id,
  Key,
  Current,
  Held,
};

/// The corpus spelling: "ok", "https", "base_https", "wifi1_psk", "held"…
const char* refusalName(Refusal refusal);

/// `http://` plus an IPv4 literal or a lowercase DNS name, an optional port
/// 1–65535 with no leading zero, and nothing else — no path, no query, no
/// userinfo, no trailing slash, never `https` (the boards have no heap for TLS).
Refusal checkBaseUrl(const char* url);

/// One WiFi profile.
struct Profile {
  char ssid[kSsidMax + 1U] = {};
  char psk[kPskMax + 1U] = {};
};

/// What a `net` object says, once adopted. `hasBase` and `hasWifi[i]` are false
/// for what the object did not name: "profiles not named are kept as they are"
/// (`provision/` `net-base-only`), so the caller MERGES this over what it has.
struct NetSet {
  uint32_t ver = 0U;
  bool hasBase = false;
  char base[kBaseUrlMax + 1U] = {};
  bool hasWifi[kProfiles] = {false, false};
  Profile wifi[kProfiles];
};

/// The adoption outcome. A struct rather than a bare refusal so the court box's
/// lane and this one can add a field without changing every call site.
struct NetResult {
  Refusal reason = Refusal::Ok;
  bool adopted() const { return reason == Refusal::Ok; }
};

/// The heartbeat's `net` object (braces included). ALL OR NOTHING: one invalid
/// field and nothing is adopted, because a half-applied network change is a
/// board on the wrong network with the wrong server. `appliedVer` is the
/// version the board runs now (0 for compiled or portal values); a `ver` not
/// above it is `not_newer` and nothing is rewritten — no flash wear.
NetResult adoptNet(const char* netObjectJson, size_t len, uint32_t appliedVer, NetSet& out);

/// The device keys a board holds: the one it authenticates with, and the one
/// before it (kept so a 401 can fall back to it — §6 step 2). At most two.
struct KeyRing {
  char currentId[kKeyIdCap] = {};
  char currentKey[kKeyLen + 1U] = {};
  bool hasPrevious = false;
  char previousId[kKeyIdCap] = {};
  char previousKey[kKeyLen + 1U] = {};
};

/// The heartbeat's `key_next` object (braces included). On `Ok`, `out` is
/// `ring` with the new key current and the old current as previous; otherwise
/// `out` is `ring` unchanged. Never adopts the key already current, nor the one
/// the board holds as previous — a rotation only ever moves forward.
Refusal adoptKeyNext(const char* keyNextJson, size_t len, const KeyRing& ring, KeyRing& out);

/// What the link supervisor tells the board to do.
enum class Action : uint8_t {
  None = 0U,
  /// Disconnect and associate again, on the next profile in the board's list.
  ReconnectNextProfile = 1U,
  /// Restart the chip. Safe on both boards: the Mega holds its relays, and the
  /// gate writes LOCKED before it drives.
  Restart = 2U,
};

const char* actionName(Action action);

/// The rule itself, pure (`provision/` `supervisor`): after `downS` seconds
/// down, `sinceAttemptS` since the last supervised reconnect (or since the
/// outage began, before the first), with `attempts` made in this outage.
Action supervise(uint32_t downS, uint32_t sinceAttemptS, uint32_t attempts);

/// The same rule, with its state, ticked by a board's loop.
///
/// The core's own reconnect is left alone for 30 s; then the board disconnects
/// and reconnects on its next profile, backing off 30, 60, 120, 240 and 300 s;
/// after fifteen minutes down it restarts the chip. Arduino-ESP32 stops
/// reconnecting FOR GOOD after `AUTH_FAIL` or `ASSOC_LEAVE` (door-gate review
/// DG-3), and a router rebooting rejects authentication exactly once while it
/// comes up — so without this a door could sit offline until a power cycle.
class Supervisor {
public:
  /// One tick. Returns what to do NOW; a reconnect is counted as made the
  /// moment it is returned, so the caller acts on it exactly once.
  Action tick(uint32_t nowMs, bool linkUp);

  /// Seconds the link has been down, 0 while up.
  uint32_t downSeconds(uint32_t nowMs) const;

  /// Supervised reconnects in the current outage.
  uint32_t attempts() const { return attempts_; }

private:
  uint32_t downSinceMs_ = 0U;
  uint32_t lastAttemptMs_ = 0U;
  uint32_t attempts_ = 0U;
  bool down_ = false;
};

} // namespace devnet

#endif // CRUSADERS_DEVNET_NET_H
